<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepName;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcUrlBuilder;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;
use Civi\Lughauth\Features\Oidc\User\Application\Usecase\RegisterUserUsecase;

class RegisterUserForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer,
        private readonly OidcUrlBuilder $urlBuilder,
        private readonly RegisterUserUsecase $registerUser
    ) {
    }

    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $body = $input->body ?? [];
        if (isset($body['user'])) {
            $user = $body['user'] ?? '';
            $accept = $body['accept'] ?? false;
            $pass  = $this->securer->decrypt($body["pass"] ?? '') ?? '';
            if ($accept !== 'accept') {
                throw new LoginException(AuthenticationResult::unknowUser($input->context->tenant, $user, 'conditions_requierd'));
            }

            $url = $this->urlBuilder->registerUserUrl(
                $input->authRequest,
                $input->context->tenant,
                $input->context->state,
                $input->context->nonce,
                '&_use_code='
            );
            $this->registerUser->requestForRegister($url, $input->context->tenant, (string) $user, $pass);
            throw new LoginException(AuthenticationResult::waitNewuserVerify($url));
        }

        $code = $this->securer->decrypt($body["code"]) ?? '';
        $csid = (string) ($body['csid'] ?? '');
        $user = $this->registerUser->verifyRegister($input->context->tenant, $code);
        if ($user !== null && $user !== '') {
            $updated = $input->challenges->withUsername($user);
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $updated,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $updated);
        }

        throw new LoginException(auth: AuthenticationResult::waitNewuserVerify('', 'Invalid code'));
    }

    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $base = rtrim($input->context->baseUrl, '/') . '/oauth';
        $locale = '';
        $params = $input->request->getQueryParams();
        if (($params['verify_send'] ?? 'false') === 'true') {
            $response = $this->paintConfirm($error, $locale, $base, $input->context->tenant, $input->challenges, $input->body ?? [], $input->request, $response);
            return StepResult::render($response, $input->challenges);
        }

        if ($error) {
            $response = $this->paintWait($error, $locale, $base, $input->context->tenant, $input->challenges, $input->body ?? [], $input->request, $response);
            return StepResult::render($response, $input->challenges);
        }

        $response = $this->paintAsk($error, $locale, $base, $input->context->tenant, $input->challenges, $input->body ?? [], $input->request, $response);
        return StepResult::render($response, $input->challenges);
    }

    private function paintAsk(?AuthenticationResult $pe, string $locale, string $base, string $tenant, ChallengesState $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("user"),
            $this->securer->cypher([['from' => 'type_pass', 'to' => 'pass']], 'regform'),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("registeruser.ask.title");
        $errorMessage = $pe?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("registeruser.ask.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("registeruser.ask.help");
        $send = $translator->get("registeruser.ask.send");
        $name = $translator->get("registeruser.ask.email");
        $pass = $translator->get("registeruser.ask.password");

        $accept = '<input type="hidden" name="accept" value="accept" />';
        $terms = $this->registerUser->getRegisterConsent($tenant);
        if ($terms !== null && $terms !== '') {
            $accept = '<input type="checkbox" name="accept" value="accept" />' .
                            '<textarea type="text" readonly>' . $terms . '</textarea>';
        }

        $backText = $translator->get(
            "registeruser.ask.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("registeruser.ask.back-label") . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $step = StepName::REGISTER_USER->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $request,
            'New pass',
            $js . <<<HTML
                    <h1> $title </h1>
                    <p> $help </p>
                    {$error}
                    <form id="regform" method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label>{$name}
                            <input type="text" name="user" id="user" value="" />
                        </label>
                        <label>{$pass}
                            <input type="password" id="type_pass" value="" />
                        </label>
                        <input type="hidden" name="pass" id="pass" value="" />
                        {$accept}
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return $response;
    }

    private function paintConfirm(?AuthenticationResult $pe, string $locale, string $base, string $tenant, ChallengesState $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $params = $request->getQueryParams();
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("type_code"),
            $this->securer->cypher([['from' => 'type_code', 'to' => 'code'] ], 'recform'),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("registeruser.code.title");
        $errorMessage = $pe?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("registeruser.code.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("registeruser.code.help");
        $send = $translator->get("registeruser.code.send");
        $code = $translator->get("registeruser.code.validation");
        $translator->get("registeruser.code.newpass");

        $backText = $translator->get(
            "registeruser.code.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("registeruser.code.back-label") . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $defaultCode = $params['_use_code'] ?? '';
        $step = StepName::REGISTER_USER->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $request,
            'New pass',
            $js . <<<HTML
                    <h1> $title </h1>
                    <p> $help </p>
                    {$error}
                    <form id="recform" method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <input type="hidden" name="code" id="code" value="" />
                        <label>{$code}
                            <input type="text" id="type_code" value="{$defaultCode}" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return $response;
    }

    private function paintWait(?AuthenticationResult $pe, string $locale, string $base, string $tenant, ChallengesState $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("type_code"),
            $this->securer->cypher([['from' => 'type_code', 'to' => 'code'],
                ['from' => 'type_new_pass', 'to' => 'new_pass']], 'recform'),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $url = $pe?->id ?? '';
        $title = $translator->get("registeruser.info.title");
        $errorMessage = $pe?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("registeruser.info.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("registeruser.info.help");
        $send = $translator->get(
            "registeruser.info.goto-text",
            ['<a href="' . $url . '">' . $translator->get("registeruser.info.goto-label") . '</a>' ]
        );

        $backText = $translator->get(
            "registeruser.info.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("registeruser.info.back-label") . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $response->getBody()->write($this->decorator->getFullPage(
            $request,
            'New pass',
            $js . <<<HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    {$send}
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return $response;
    }
}
